// Self-Supplying Pond — loads ONLY assets generated by GMI Cloud models (see assets/manifest.json).
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { OBJLoader } from 'three/addons/loaders/OBJLoader.js';
import { MTLLoader } from 'three/addons/loaders/MTLLoader.js';
import { FBXLoader } from 'three/addons/loaders/FBXLoader.js';

const params = new URLSearchParams(location.search);
const DEMO = params.has('demo');          // autopilot for recordings
const POND_R = 18;

const $ = (id) => document.getElementById(id);
const renderer = new THREE.WebGLRenderer({ canvas: $('c'), antialias: true, preserveDrawingBuffer: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.shadowMap.enabled = true;
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 500);
addEventListener('resize', () => { camera.aspect = innerWidth / innerHeight; camera.updateProjectionMatrix(); renderer.setSize(innerWidth, innerHeight); });

// ---------- load manifest + assets ----------
const manifest = await (await fetch(import.meta.env.BASE_URL + 'manifest.json')).json();
const fileFor = (id) => manifest.steps.find((s) => s.id === id && s.status === 'success');
const urlOf = (p) => import.meta.env.BASE_URL + p.replace(/^assets\//, '');

export const usedKinds = {};
async function loadEntity(id) {
  try { const m = await loadMesh(id); usedKinds[id] = 'mesh'; return m; }
  catch (err) {
    console.warn(`[assets] ${id}: no 3D mesh (${err.message}); using GMI sprite`);
    usedKinds[id] = 'sprite'; return loadSprite(id);
  }
}
async function loadSprite(id) {
  const e = fileFor(`${id}_sprite`);
  if (!e) throw new Error(`no mesh or sprite for ${id}`);
  const t = await texLoader.loadAsync(urlOf(e.files[0].file));
  t.colorSpace = THREE.SRGBColorSpace;
  const img = t.image, aspect = img.width / img.height;
  const mat = new THREE.MeshStandardMaterial({ map: t, transparent: true, alphaTest: 0.35, side: THREE.DoubleSide, roughness: 0.8 });
  const plane = new THREE.Mesh(new THREE.PlaneGeometry(aspect, 1), mat);
  plane.position.y = 0.5; plane.castShadow = true;
  plane.customDepthMaterial = new THREE.MeshDepthMaterial({ map: t, alphaTest: 0.35, depthPacking: THREE.RGBADepthPacking });
  plane.userData.isBillboard = true;
  const holder = new THREE.Group(); holder.add(plane); return holder;
}
async function loadMesh(id) {
  const e = fileFor(id);
  if (!e) throw new Error(`no mesh generated`);
  const files = [...(e.mesh_files || []), ...e.files.map((f) => f.file)];
  const pick = (ext) => files.find((f) => f.toLowerCase().endsWith(ext));
  let obj;
  if (pick('.glb') || pick('.gltf')) obj = (await new GLTFLoader().loadAsync(urlOf(pick('.glb') || pick('.gltf')))).scene;
  else if (pick('.obj')) {
    const mtl = pick('.mtl');
    const loader = new OBJLoader();
    if (mtl) { const m = await new MTLLoader().setPath(urlOf(path_dir(mtl)) + '/').loadAsync(mtl.split('/').pop()); m.preload(); loader.setMaterials(m); }
    obj = await loader.loadAsync(urlOf(pick('.obj')));
  } else if (pick('.fbx')) obj = await new FBXLoader().loadAsync(urlOf(pick('.fbx')));
  else throw new Error(`unknown mesh format for ${id}: ${files.join(',')}`);
  return normalize(obj);
}
function path_dir(p) { return p.split('/').slice(0, -1).join('/'); }
function normalize(obj, size = 1) {
  const box = new THREE.Box3().setFromObject(obj);
  const s = box.getSize(new THREE.Vector3());
  const c = box.getCenter(new THREE.Vector3());
  obj.position.sub(c);
  obj.position.y += s.y / 2;
  const wrap = new THREE.Group();
  wrap.add(obj);
  wrap.scale.setScalar(size / Math.max(s.x, s.y, s.z));
  obj.traverse((o) => { if (o.isMesh) { o.castShadow = true; if (o.material) o.material.side = THREE.FrontSide; } });
  const holder = new THREE.Group(); holder.add(wrap); return holder;
}

const texLoader = new THREE.TextureLoader();
const tex = (id) => texLoader.loadAsync(urlOf(fileFor(id).files[0].file));
const [playerProto, gemProto, rockProto, waterTex, skyTex] = await Promise.all([
  loadEntity('player'), loadEntity('collectible'), loadEntity('obstacle'), tex('ground'), tex('sky'),
]);
console.log('[assets] kinds', JSON.stringify(usedKinds));

// ---------- world ----------
const pal = manifest.game.palette || {};
// painted sky wraps around the pond on a big open cylinder (mirrored so there is no seam)
skyTex.colorSpace = THREE.SRGBColorSpace;
skyTex.wrapS = THREE.MirroredRepeatWrapping; skyTex.repeat.set(2, 1);
const sky = new THREE.Mesh(new THREE.CylinderGeometry(150, 150, 110, 64, 1, true),
  new THREE.MeshBasicMaterial({ map: skyTex, side: THREE.BackSide, fog: false }));
sky.position.y = 38; scene.add(sky);
scene.background = new THREE.Color(pal.fog || '#f6c99b');
scene.fog = new THREE.Fog(pal.fog || '#f6c99b', 60, 160);

waterTex.wrapS = waterTex.wrapT = THREE.MirroredRepeatWrapping;
waterTex.repeat.set(4, 4);
waterTex.colorSpace = THREE.SRGBColorSpace;
const water = new THREE.Mesh(new THREE.CircleGeometry(POND_R + 0.5, 96),
  new THREE.MeshStandardMaterial({ map: waterTex, roughness: 0.35, metalness: 0.05 }));
water.rotation.x = -Math.PI / 2; water.receiveShadow = true; scene.add(water);
// soft shore ring + outer grass (plain colours, no files)
const shore = new THREE.Mesh(new THREE.RingGeometry(POND_R + 0.5, POND_R + 2.2, 96),
  new THREE.MeshStandardMaterial({ color: '#f1d9a8', roughness: 1, flatShading: true }));
shore.rotation.x = -Math.PI / 2; shore.position.y = 0.02; scene.add(shore);
const grass = new THREE.Mesh(new THREE.RingGeometry(POND_R + 2.2, 120, 64),
  new THREE.MeshStandardMaterial({ color: '#9fcf8a', roughness: 1 }));
grass.rotation.x = -Math.PI / 2; grass.position.y = 0.01; scene.add(grass);

scene.add(new THREE.HemisphereLight('#ffe9c9', '#5b7a8c', 1.4));
const sun = new THREE.DirectionalLight('#ffd9a0', 2.4);
sun.position.set(-14, 22, 10); sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
Object.assign(sun.shadow.camera, { left: -25, right: 25, top: 25, bottom: -25 });
scene.add(sun);

// ---------- entities ----------
const player = playerProto; player.scale.setScalar(3); scene.add(player);
const gems = [], rocks = [];
function spawnGem(g) {
  const a = Math.random() * Math.PI * 2, r = 3 + Math.random() * (POND_R - 5);
  g.position.set(Math.cos(a) * r, 0.4, Math.sin(a) * r); g.userData.t = Math.random() * 10;
}
for (let i = 0; i < 6; i++) { const g = gemProto.clone(); g.scale.setScalar(1.7); spawnGem(g); gems.push(g); scene.add(g); }
function addRock() {
  const r = rockProto.clone(); r.scale.setScalar(2.6);
  const a = Math.random() * Math.PI * 2; r.position.set(Math.cos(a) * (POND_R - 2), 0, Math.sin(a) * (POND_R - 2));
  const d = Math.random() * Math.PI * 2; r.userData.v = new THREE.Vector2(Math.cos(d), Math.sin(d));
  rocks.push(r); scene.add(r);
}

// ---------- audio ----------
const music = fileFor('music') ? new Audio(urlOf(fileFor('music').files[0].file)) : null;
if (music) { music.loop = true; music.volume = 0.55; }
const voice = fileFor('voice') ? new Audio(urlOf(fileFor('voice').files[0].file)) : null;

// ---------- UI ----------
$('title').textContent = manifest.game.title;
$('ov-title').textContent = manifest.game.title;
$('ov-tag').textContent = manifest.game.tagline;
$('ov-how').textContent = manifest.game.how_to_play + '  (WASD / arrows / drag)';
$('start').disabled = false; $('start').textContent = 'start';

let state = 'menu', score = 0, lives = 3, invuln = 0, speed = 6;
const renderLives = () => ($('lives').textContent = '♥'.repeat(lives) + '♡'.repeat(Math.max(0, 3 - lives)));
function start() {
  score = 0; lives = 3; invuln = 0; $('score').textContent = 0; renderLives();
  rocks.splice(0).forEach((r) => scene.remove(r)); addRock(); addRock();
  player.position.set(0, 0, 0);
  state = 'play'; $('overlay').classList.add('hidden');
  if (voice) { voice.currentTime = 0; voice.play().catch(() => {}); }
  if (music) { music.currentTime = 0; setTimeout(() => music.play().catch(() => {}), voice ? 300 : 0); }
}
$('start').onclick = start;
if (DEMO) { $('overlay').style.display = 'none'; start(); }
renderLives();

// ---------- input ----------
const keys = {};
addEventListener('keydown', (e) => { keys[e.key.toLowerCase()] = true; if (state !== 'play' && (e.key === 'Enter' || e.key === ' ')) start(); });
addEventListener('keyup', (e) => (keys[e.key.toLowerCase()] = false));
let pointer = null;
const ray = new THREE.Raycaster(), plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
function toWorld(e) { const v = new THREE.Vector2((e.clientX / innerWidth) * 2 - 1, -(e.clientY / innerHeight) * 2 + 1); ray.setFromCamera(v, camera); const p = new THREE.Vector3(); ray.ray.intersectPlane(plane, p); return p; }
$('c').addEventListener('pointerdown', (e) => (pointer = toWorld(e)));
$('c').addEventListener('pointermove', (e) => { if (pointer) pointer = toWorld(e); });
addEventListener('pointerup', () => (pointer = null));

function autopilot() {
  let target = gems.reduce((b, g) => (g.position.distanceTo(player.position) < b.position.distanceTo(player.position) ? g : b));
  const dir = new THREE.Vector3().subVectors(target.position, player.position).setY(0).normalize();
  for (const r of rocks) { const away = new THREE.Vector3().subVectors(player.position, r.position).setY(0); const d = away.length(); if (d < 5) dir.add(away.normalize().multiplyScalar((5 - d) * 0.9)); }
  return dir.normalize();
}

// ---------- loop ----------
const clockT = new THREE.Timer();
const camOffset = new THREE.Vector3(0, 11.5, 22);
let heading = 0, facing = 1;
const _q = new THREE.Quaternion();
function tick() {
  clockT.update(); const dt = Math.min(clockT.getDelta(), 0.05), t = clockT.getElapsed();
  waterTex.offset.set(Math.sin(t * 0.1) * 0.05, t * 0.012);
  if (state === 'play') {
    const dir = new THREE.Vector3((keys.d || keys.arrowright ? 1 : 0) - (keys.a || keys.arrowleft ? 1 : 0), 0, (keys.s || keys.arrowdown ? 1 : 0) - (keys.w || keys.arrowup ? 1 : 0));
    if (pointer) dir.subVectors(pointer, player.position).setY(0).clampLength(0, 1);
    if (DEMO) dir.copy(autopilot());
    if (dir.lengthSq() > 0.001) {
      dir.normalize(); player.position.addScaledVector(dir, speed * dt);
      if (Math.abs(dir.x) > 0.2) facing = dir.x < 0 ? -1 : 1;
      const target = Math.atan2(dir.x, dir.z); let d = target - heading; d = Math.atan2(Math.sin(d), Math.cos(d)); heading += d * Math.min(1, dt * 10);
    }
    const r = Math.hypot(player.position.x, player.position.z);
    if (r > POND_R - 1) player.position.multiplyScalar((POND_R - 1) / r);
    player.rotation.y = heading;
    player.traverse((o) => { if (o.userData.isBillboard) o.scale.x += (facing - o.scale.x) * Math.min(1, dt * 12); });
    player.position.y = Math.sin(t * 4) * 0.08;
    for (const g of gems) {
      g.userData.t += dt; g.rotation.y += dt * 1.6; g.position.y = 0.5 + Math.sin(g.userData.t * 2.5) * 0.25;
      if (g.position.distanceTo(player.position) < 1.6) { score++; $('score').textContent = score; spawnGem(g); if (score % 5 === 0 && rocks.length < 6) addRock(); }
    }
    const rockSpeed = 2.2 + score * 0.12;
    for (const k of rocks) {
      k.position.x += k.userData.v.x * rockSpeed * dt; k.position.z += k.userData.v.y * rockSpeed * dt; k.rotation.y += dt * 0.4;
      const rr = Math.hypot(k.position.x, k.position.z);
      if (rr > POND_R - 1.5) { const n = new THREE.Vector2(k.position.x / rr, k.position.z / rr); const v = k.userData.v; const dot = v.dot(n); v.sub(n.multiplyScalar(2 * dot)); k.position.multiplyScalar((POND_R - 1.6) / rr); }
      if (invuln <= 0 && k.position.distanceTo(player.position) < 1.9) {
        lives--; renderLives(); invuln = 1.6;
        if (lives <= 0) { state = 'over'; $('ov-title').textContent = `score ${score}`; $('ov-tag').textContent = 'the pond thanks you.'; $('start').textContent = 'again'; $('overlay').classList.remove('hidden'); if (DEMO) start(); }
      }
    }
    invuln -= dt; player.visible = invuln > 0 ? Math.floor(t * 12) % 2 === 0 : true;
  } else {
    player.rotation.y += dt * 0.6;
    gems.forEach((g) => (g.rotation.y += dt));
  }
  const camTarget = state === 'play' ? player.position.clone().multiplyScalar(0.5) : new THREE.Vector3();
  camera.position.lerp(camTarget.clone().add(camOffset), 0.06);
  camera.lookAt(camTarget.clone().add(new THREE.Vector3(0, 0, -4)));
  scene.traverse((o) => { if (o.userData.isBillboard) { o.parent.getWorldQuaternion(_q); o.quaternion.copy(_q.invert().multiply(camera.quaternion)); } });
  renderer.render(scene, camera);
  requestAnimationFrame(tick);
}
tick();
window.__game = { usedKinds, get musicPlaying() { return music ? !music.paused : false; }, get musicTime() { return music ? music.currentTime : 0; }, get state() { return state; }, get score() { return score; } };
